import request from '@/utils/requests'

// 根据体条件搜索商品
export const search = (categoryId, goodsName) => {
  return request({
    method: 'POST',
    url: '/goods/list',
    params: {
      categoryId,
      goodsName
    }
  })
}

// 获取商品详细数据
export const searchById = (id) => {
  return request({
    method: 'GET',
    url: '/goods/detail',
    params: {
      goodsId: String(id)
    }
  })
}

// 获取商品评价
export const getProComments = (goodsId, limit) => {
  return request.get('/comment/listRows', {
    params: {
      goodsId,
      limit
    }
  })
}
