<template>
  <!-- 有数据再渲染，开发模式下防止vue报错 -->
  <div id="detailBox" v-if="detail">

    <div class="navBar">
      <van-nav-bar title="商品详情页" left-text="返回" left-arrow @click-left="onClickLeft" fixed z-index="999" />
    </div>

    <!-- 轮播图 -->
    <div class="image">
      <van-swipe class="my-swipe" :autoplay="3000" @change="onChange">
        <van-swipe-item v-for="(item) in detail.goods_images" :key="item.file_id">
          <img :src="item.external_url">
        </van-swipe-item>
        <template #indicator>
          <div class="custom-indicator">{{ currentIndex }}/{{ detail.goods_images.length }}</div>
        </template>
      </van-swipe>
    </div>

    <!-- 描述 -->
    <div class="word">
      <div class="price">
        <span class="new">￥{{ detail.goods_price_max }}</span>
        <span class="old">￥{{ detail.line_price_min }}</span>
        <span class="count">已售{{ detail.goods_sales }}件</span>
      </div>
      <div class="title-box">
        <span class="title">{{ detail.goods_name }}</span>
      </div>
    </div>

    <!-- 服务 -->
    <div class="service">
      <div class="left-words">
        <span><van-icon name="passed" />七天无理由退货</span>
        <span><van-icon name="passed" />48小时发货</span>
      </div>
      <div class="right-icon">
        <van-icon name="arrow" />
      </div>
    </div>

    <!-- 商品评价 -->
    <div class="comment">
      <div class="comment-title">
        <div class="left">商品评价 ({{ totalComment }}条)</div>
        <div class="right">查看更多 <van-icon name="arrow" /> </div>
      </div>
      <div class="comment-list">
        <div class="comment-item" v-for="item in comments" :key="item.comment_id">
          <div class="top">
            <!-- v-if v-else处理用户没有图片 -->
            <img :src="item.user.avatar_url" alt="" v-if="item.user.avatar_url !== null">
            <img src="https://img1.baidu.com/it/u=3598104138,3632108415&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=800"
              v-else>
            <div class="name">{{ item.user.nick_name }}</div>
            <van-rate :size="16" :value="(item.score / 2)" color="#ffd21e" void-icon="star" void-color="#eee" />
          </div>
          <div class="content">
            <span>{{ item.content }}</span>
          </div>
          <div class="time">
            {{ item.create_time }}
          </div>
        </div>
      </div>
    </div>

    <!-- 商品描述 -->
    <div class="detail" v-html="detail.content">
    </div>

    <!-- 添加购物车按钮 -->
    <div class="cart">
      <van-goods-action>
        <van-goods-action-icon icon="wap-home-o" text="首页" @click="$router.push('/')" />
        <!-- 通过v-if实现购物车没有东西是不显示右上角红圆点 -->
        <van-goods-action-icon icon="cart-o" text="购物车" :badge="cartTotal" v-if="cartTotal > 0"
          @click="$router.push('/cart')" />
        <van-goods-action-icon icon="cart-o" text="购物车" v-else @click="$router.push('/cart')" />
        <van-goods-action-button color="#be99ff" type="warning" text="加入购物车" @click="clickCart" />
        <van-goods-action-button color="#7232dd" type="danger" text="立即购买" @click="clickRightNow" />
      </van-goods-action>
    </div>

    <!-- 弹层 -->
    <div class="actionSheet">
      <van-action-sheet v-model="show" :title="mode === 1 ? '加入购物车' : '立刻购买'">
        <div class="product">
          <div class="product-title">
            <div class="left">
              <img :src="detail.goods_image">
            </div>
            <div class="right">
              <div class="price">
                <span>¥</span>
                <span class="nowprice">{{ detail.goods_price_min }}</span>
              </div>
              <div class="count">
                <span>库存</span>
                <span>{{ detail.stock_total }}</span>
              </div>
            </div>
          </div>
          <div class="num-box">
            <span>数量</span>
            <!-- 这里用v-model修改数据是因为，buyCount为该组件自己维护的数据，不是vuex中的数据，没有违背单向数据流 -->
            <CountBox v-model="buyCount"></CountBox>
          </div>
          <div class="showbtn" v-if="detail.stock_total > 0">
            <div class="btn" v-if="mode === 1" @click="addCart">加入购物车</div>
            <div class="btn now" v-else @click="buyRightnow">立即购买</div>
          </div>
          <div class="btn-none" v-else>该商品已抢完</div>
        </div>
      </van-action-sheet>
    </div>

  </div>
</template>

<script>
import { addCart } from '@/api/cart'
import { searchById, getProComments } from '@/api/product'
import CountBox from '@/components/CountBox.vue'
import loginConfirm from '@/mixins/loginConfirm'

export default {
  name: 'ProdetailIndex',
  mixins: [loginConfirm],
  data () {
    return {
      goodsId: 0,
      detail: null,
      currentIndex: 1,
      comments: [],
      totalComment: '',
      show: false,
      mode: 0,
      buyCount: 1,
      cartTotal: 0
    }
  },
  methods: {
    onClickLeft () {
      // this.$router.push('/searchList')
      this.$router.go(-1)
    },
    onChange () {
      if (this.currentIndex === this.detail.goods_images.length) {
        this.currentIndex = 1
        return
      }
      this.currentIndex++
    },
    async getDetail () {
      // 获取商品信息
      this.goodsId = this.$route.query.id
      const response = await searchById(this.goodsId)
      this.detail = response.data.detail
      // console.log('detai', response)
    },
    async getProComments () {
      const response = await getProComments(this.goodsId, 3)
      this.comments = response.data.list
      this.totalComment = response.data.total
      // console.log('comment', response)
    },
    clickCart () {
      this.mode = 1
      this.show = true
    },
    clickRightNow () {
      this.mode = 2
      this.show = true
    },
    async addCart () {
      if (this.loginConfirm()) {
        return
      }
      const response = await addCart(this.goodsId, this.buyCount, this.detail.skuList[0].goods_sku_id)
      this.cartTotal = response.data.cartTotal
      this.$toast('加入购物车成功')
      this.show = false
    },
    buyRightnow () {
      if (this.loginConfirm()) {
        return
      }
      this.$router.push({
        path: '/pay',
        query: {
          mode: 'buyNow',
          goodsId: this.goodsId,
          goodsSkuId: this.detail.skuList[0].goods_sku_id,
          goodsNum: this.buyCount
        }
      })
      // console.log('buyRightnow')
    }

  },
  async created () {
    // 并行调用Ajax，加快访问速度，如果全部写在created中则要等前一个请求完才发第二个请求
    // 获取商品信息
    this.getDetail()
    // 获取评价
    this.getProComments()
  },
  components: {
    CountBox
  }
}
</script>

<style scoped lang="less">
#detailBox {
  margin-top: 46px;
  margin-bottom: 50px;

  .image {

    img {
      width: 100%;
    }

    .custom-indicator {
      position: absolute;
      right: 5px;
      bottom: 5px;
      padding: 2px 5px;
      font-size: 12px;
      background: rgba(0, 0, 0, 0.1);
    }
  }

  .word {
    padding: 5px 10px;
    line-height: 26px;

    span {
      line-height: 22px;
      color: #616161;
    }

    .count {
      font-size: 14px;
      margin-left: 120px;
    }

    .title {
      font-size: 14px;
    }

    .price {

      .new {
        font-size: 18px;
        color: rgb(189, 67, 67);
      }

      .old {
        font-size: 12px;
        margin-left: 8px;
        color: #929292;
        text-decoration: line-through;
      }
    }
  }

  .service {
    display: flex;
    justify-content: space-between;
    line-height: 40px;
    margin-top: 10px;
    font-size: 16px;
    background-color: #fafafa;

    .left-words {
      span {
        margin-right: 10px;
      }

      .van-icon {
        margin-right: 4px;
        color: #fa2209;
      }
    }
  }

  .comment {
    padding: 10px;

    .comment-title {
      display: flex;
      justify-content: space-between;

      .right {
        color: #959595;
      }

    }

    .comment-item {
      font-size: 16px;
      line-height: 30px;

      .top {
        height: 30px;
        display: flex;
        align-items: center;
        margin-top: 20px;

        img {
          width: 20px;
          height: 20px;
        }

        .name {
          margin: 0 10px;
        }
      }

      // 用户评价太长问题
      .content {
        span {
          width: 350px;
          display: inline-block;
          overflow: hidden;
        }
      }

      .time {
        color: #999;
      }
    }
  }

  // 这段css有点难懂
  .detail {
    width: 100%;
    overflow: scroll;

    ::v-deep img {
      display: block;
      width: 100% !important;
    }
  }

  .cart {
    z-index: 999;
  }

  .product {
    .product-title {
      display: flex;

      .left {
        img {
          width: 90px;
          height: 90px;
        }

        margin: 10px;
      }

      .right {
        flex: 1;
        padding: 10px;

        .price {
          font-size: 14px;
          color: #fe560a;

          .nowprice {
            font-size: 24px;
            margin: 0 5px;
          }
        }
      }
    }

    .num-box {
      display: flex;
      justify-content: space-between;
      padding: 10px;
      align-items: center;
    }

    .btn,
    .btn-none {
      height: 40px;
      line-height: 40px;
      margin: 20px;
      border-radius: 20px;
      text-align: center;
      color: rgb(255, 255, 255);
      background-color: rgb(255, 148, 2);
    }

    .btn.now {
      background-color: #fe5630;
    }

    .btn-none {
      background-color: #cccccc;
    }
  }
}
</style>
